import{_ as a,o,c as t,a5 as i}from"./chunks/framework.CXvGqWf0.js";const u=JSON.parse('{"title":"漫画 · 第 12 话 语义化标签：让机器读懂你的页面","description":"","frontmatter":{},"headers":[],"relativePath":"comics/html/EP.12-semantic.md","filePath":"comics/html/EP.12-semantic.md","lastUpdated":1793421609000}'),d={name:"comics/html/EP.12-semantic.md"};function c(l,e,r,n,s,h){return o(),t("div",null,[...e[0]||(e[0]=[i('<h1 id="漫画-·-第-12-话-语义化标签-让机器读懂你的页面" tabindex="-1">漫画 · 第 12 话 语义化标签：让机器读懂你的页面 <a class="header-anchor" href="#漫画-·-第-12-话-语义化标签-让机器读懂你的页面" aria-label="Permalink to &quot;漫画 · 第 12 话 语义化标签：让机器读懂你的页面&quot;">​</a></h1><blockquote><p>对应正文：<a href="./../../docs/html/01-semantic">docs/html/01-semantic.md</a> ｜ 原画：<a href="./EP.12-semantic.svg">EP.12-semantic.svg</a></p></blockquote><h2 id="登场角色" tabindex="-1">登场角色 <a class="header-anchor" href="#登场角色" aria-label="Permalink to &quot;登场角色&quot;">​</a></h2><ul><li><strong>像素酱</strong>：CSS 造型师，HTML 篇第一话就被拉来接手祖传页面——满屏 <code>&lt;div class=&quot;box1&quot;&gt;</code>，她想找正文区，搜索引擎和读屏器也想。</li><li><strong>标签君</strong>：HTML5 结构师，本话主角。掏出一张&quot;标签 → ARIA 角色&quot;映射表，证明好标签名本身就是文档。</li></ul><h2 id="剧情梗概" tabindex="-1">剧情梗概 <a class="header-anchor" href="#剧情梗概" aria-label="Permalink to &quot;剧情梗概&quot;">​</a></h2><p>HTML5 之前，页面结构全靠 <code>&lt;div class=&quot;header&quot;&gt;</code> 这类私人命名表达，机器完全看不懂。语义化标签把&quot;这是什么内容&quot;写进了标签名：<code>header/nav/main/article/section/aside/footer</code> 在无障碍树里自动成为地标，搜索引擎能定位正文，屏幕阅读器能带着用户在区块间跳转。标签君还顺手用 <code>details/summary</code> 零 JS 写了个手风琴。</p><h2 id="分格解读" tabindex="-1">分格解读 <a class="header-anchor" href="#分格解读" aria-label="Permalink to &quot;分格解读&quot;">​</a></h2><h3 id="格1-·-痛点现场" tabindex="-1">格1 · 痛点现场 <a class="header-anchor" href="#格1-·-痛点现场" aria-label="Permalink to &quot;格1 · 痛点现场&quot;">​</a></h3><p><code>&lt;div&gt;</code> 和 <code>&lt;span&gt;</code> 是无语义的通用容器，只承担布局和样式钩子。<code>class=&quot;header&quot;</code> 只有作者自己看得懂——爬虫无法区分导航与正文，读屏器列不出可跳转的地标，半年后队友回看代码，结构与样式缠绕在一起不敢重构。</p><h3 id="格2-·-机制登场" tabindex="-1">格2 · 机制登场 <a class="header-anchor" href="#格2-·-机制登场" aria-label="Permalink to &quot;格2 · 机制登场&quot;">​</a></h3><p>每个语义元素在无障碍树中自带一个隐式 ARIA 角色：页面级 <code>header → banner</code>、<code>nav → navigation</code>、<code>main → main</code>、<code>aside → complementary</code>、<code>footer → contentinfo</code>。写原生标签等于免费拿到 role <strong>外加</strong>键盘行为（比如 <code>summary</code> 可聚焦、Enter/Space 开合）；事后用 <code>div + role + tabindex + keydown</code> 补救总会漏掉一环。这就是 ARIA 第一规则：能用原生就别用 ARIA。</p><h3 id="格3-·-落地收束" tabindex="-1">格3 · 落地收束 <a class="header-anchor" href="#格3-·-落地收束" aria-label="Permalink to &quot;格3 · 落地收束&quot;">​</a></h3><p>一个语义完整的页面骨架：<code>header(+nav) → main(article &gt; section) + aside → footer</code>，地标地图一次成型。行内标签各司其职：<code>details/summary</code> 零 JS 手风琴、<code>time datetime</code> 给日期机器可读格式、<code>figure/figcaption</code> 把图和说明绑成可整体搬移的单元、<code>mark/strong/em</code> 视觉相近但语义不同。多个 <code>nav/aside</code> 记得用 <code>aria-label</code> 区分；<code>&lt;main&gt;</code> 每页最多一个；标题按字面 h1→h2→h3 递进——曾经的&quot;分段大纲算法&quot;从未被任何浏览器实现，已从规范废弃。</p><h2 id="码叔划重点" tabindex="-1">码叔划重点 <a class="header-anchor" href="#码叔划重点" aria-label="Permalink to &quot;码叔划重点&quot;">​</a></h2><ol><li>div/span 是无语义通用容器；结构标签名即含义，SEO 与读屏器直接读出角色。</li><li>语义标签 ≈ 免费 ARIA role 加键盘行为——能用原生就别用 ARIA 补救。</li><li>main 每页唯一；标题按字面 h1→h2→h3 递进不跳级，大纲算法从未实现。</li></ol><h2 id="自测一题" tabindex="-1">自测一题 <a class="header-anchor" href="#自测一题" aria-label="Permalink to &quot;自测一题&quot;">​</a></h2><p><strong>问</strong>：把 <code>&lt;div class=&quot;nav&quot;&gt;</code> 改成 <code>&lt;nav&gt;</code>，页面视觉没有任何变化，收益到底在哪？</p><p><strong>答</strong>：收益在无障碍树和机器可读性。<code>&lt;nav&gt;</code> 隐式角色是 <code>navigation</code>，屏幕阅读器会把它列为可跳转地标，用户不必逐行听完整页；搜索引擎也能把导航链接与正文区分开。此外语义元素常附带原生交互（<code>details</code> 的开合、<code>summary</code> 的键盘激活），这些都是 <code>div + class</code> 无法提供的。多个 nav 时再配 <code>aria-label=&quot;主导航&quot;</code> 区分用途。</p><h2 id="动手实验" tabindex="-1">动手实验 <a class="header-anchor" href="#动手实验" aria-label="Permalink to &quot;动手实验&quot;">​</a></h2><ul><li>文档结构标签 + 地标导航可视化 + div 滥用反模式对比：<a href="./../../examples/html/01-semantic/index-01-landmark-structure.html">examples/html/01-semantic/index-01-landmark-structure.html</a></li><li>details/summary 手风琴、time、figure、mark、strong/em/b/i 语义对比：<a href="./../../examples/html/01-semantic/index-02-inline-semantic.html">index-02-inline-semantic.html</a></li><li>标题大纲分析器：实时扫描 DOM 输出语义体检报告：<a href="./../../examples/html/01-semantic/index-03-outline-analyzer.html">index-03-outline-analyzer.html</a></li></ul><h2 id="下一话预告" tabindex="-1">下一话预告 <a class="header-anchor" href="#下一话预告" aria-label="Permalink to &quot;下一话预告&quot;">​</a></h2><p>第 13 话《表单》——把校验下沉给浏览器：输入类型、约束管线与 Constraint Validation API。</p>',22)])])}const q=a(d,[["render",c]]);export{u as __pageData,q as default};
